-- 由 tools/build_room_rule_seed.py 从 1.5.4 归档规则配置生成，请勿手改。
-- 源目录: artifacts/zhejiang_game_lobby_1.5.4/recovered/hotfix-all/res/configure/900038/box/

CREATE SEQUENCE room_number_seq START WITH 1 INCREMENT BY 1;

ALTER TABLE game_rooms
    ADD COLUMN creation_idempotency_key VARCHAR(128),
    ADD COLUMN creation_request_hash VARCHAR(64),
    ADD COLUMN version BIGINT NOT NULL DEFAULT 0;

CREATE UNIQUE INDEX uk_game_rooms_owner_idempotency
    ON game_rooms(owner_user_id, creation_idempotency_key)
    WHERE creation_idempotency_key IS NOT NULL;

CREATE TABLE room_participants (
    room_id UUID NOT NULL REFERENCES game_rooms(id) ON DELETE CASCADE,
    user_id UUID NOT NULL REFERENCES app_users(id) ON DELETE CASCADE,
    joined_at TIMESTAMPTZ NOT NULL,
    PRIMARY KEY (room_id, user_id)
);

CREATE INDEX idx_room_participants_user
    ON room_participants(user_id);

DROP INDEX uk_room_card_ledger_room_charge;

CREATE UNIQUE INDEX uk_room_card_ledger_room_user_charge
    ON room_card_ledger(room_id, user_id)
    WHERE reason = 'ROOM_CREATE';

